package com.loja.pedidos;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

@SpringBootTest
class PedidoFluxoTest {

    @Autowired
    private WebApplicationContext contexto;

    private final ObjectMapper mapper = new ObjectMapper();

    private MockMvc mockMvc() {
        return MockMvcBuilders.webAppContextSetup(contexto).build();
    }

    private JsonNode criar(MockMvc mvc, double valorProdutos, double frete) throws Exception {
        MvcResult resultado = mvc.perform(post("/pedidos")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"valorProdutos\": " + valorProdutos + ", \"frete\": " + frete + "}"))
                .andExpect(MockMvcRequestBuilders.status().isCreated().matcher())
                .andReturn();
        return mapper.readTree(resultado.getResponse().getContentAsString());
    }

    private JsonNode agir(MockMvc mvc, String id, String acao) throws Exception {
        MvcResult resultado = mvc.perform(post("/pedidos/" + id + "/acoes")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"acao\": \"" + acao + "\"}"))
                .andReturn();
        return mapper.readTree(resultado.getResponse().getContentAsString());
    }

    @Test
    void exemplo1_cancelarEmSeparacaoAplicaTaxa() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 200.00, 20.00);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        agir(mvc, id, "SEPARAR");
        JsonNode resultado = agir(mvc, id, "CANCELAR");

        assertEquals("CANCELADO", resultado.get("situacao").asText());
        assertEquals(220.00, resultado.get("valorTotal").asDouble());
        assertEquals(205.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(true, resultado.get("estoqueDevolvido").asBoolean());
        assertEquals(false, resultado.get("coletaAgendada").asBoolean());
    }

    @Test
    void exemplo2_devolucaoAposEntrega() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 150.00, 12.50);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        agir(mvc, id, "SEPARAR");
        agir(mvc, id, "ENVIAR");
        agir(mvc, id, "ENTREGAR");
        JsonNode resultado = agir(mvc, id, "DEVOLVER");

        assertEquals("DEVOLVIDO", resultado.get("situacao").asText());
        assertEquals(162.50, resultado.get("valorTotal").asDouble());
        assertEquals(150.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(false, resultado.get("estoqueDevolvido").asBoolean());
        assertEquals(true, resultado.get("coletaAgendada").asBoolean());
    }

    @Test
    void exemplo3_cancelarAguardandoPagamentoSemReembolso() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 80.00, 0.00);
        String id = pedido.get("id").asText();

        JsonNode resultado = agir(mvc, id, "CANCELAR");

        assertEquals("CANCELADO", resultado.get("situacao").asText());
        assertEquals(0.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(false, resultado.get("estoqueDevolvido").asBoolean());
        assertEquals(false, resultado.get("coletaAgendada").asBoolean());
    }

    @Test
    void exemplo4_cancelarPagoReembolsaTotal() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 250.00, 25.00);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        JsonNode resultado = agir(mvc, id, "CANCELAR");

        assertEquals("CANCELADO", resultado.get("situacao").asText());
        assertEquals(275.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(false, resultado.get("estoqueDevolvido").asBoolean());
    }

    @Test
    void exemplo5_taxaMaiorQueTotalNaoFicaNegativa() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 10.00, 3.00);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        agir(mvc, id, "SEPARAR");
        JsonNode resultado = agir(mvc, id, "CANCELAR");

        assertEquals("CANCELADO", resultado.get("situacao").asText());
        assertEquals(13.00, resultado.get("valorTotal").asDouble());
        assertEquals(0.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(true, resultado.get("estoqueDevolvido").asBoolean());
    }

    @Test
    void exemplo6_enviarSemSepararDaErro() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 99.90, 15.00);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        MvcResult resultado = mvc.perform(post("/pedidos/" + id + "/acoes")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"acao\": \"ENVIAR\"}"))
                .andReturn();

        assertEquals(409, resultado.getResponse().getStatus());
        JsonNode corpo = mapper.readTree(resultado.getResponse().getContentAsString());
        assertEquals("ACAO_NAO_PERMITIDA", corpo.get("erro").asText());

        JsonNode atual = mapper.readTree(mvc.perform(get("/pedidos/" + id)).andReturn().getResponse().getContentAsString());
        assertEquals("PAGO", atual.get("situacao").asText());
    }

    @Test
    void exemplo7_cancelarEnviadoDaErro() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 100.00, 10.00);
        String id = pedido.get("id").asText();

        agir(mvc, id, "PAGAR");
        agir(mvc, id, "SEPARAR");
        agir(mvc, id, "ENVIAR");

        MvcResult resultado = mvc.perform(post("/pedidos/" + id + "/acoes")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"acao\": \"CANCELAR\"}"))
                .andReturn();

        assertEquals(409, resultado.getResponse().getStatus());
        JsonNode atual = mapper.readTree(mvc.perform(get("/pedidos/" + id)).andReturn().getResponse().getContentAsString());
        assertEquals("ENVIADO", atual.get("situacao").asText());
    }

    @Test
    void exemplo8_acaoInexistente() throws Exception {
        MockMvc mvc = mockMvc();
        JsonNode pedido = criar(mvc, 50.00, 5.00);
        String id = pedido.get("id").asText();

        MvcResult resultado = mvc.perform(post("/pedidos/" + id + "/acoes")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"acao\": \"TROCAR\"}"))
                .andReturn();

        assertEquals(400, resultado.getResponse().getStatus());
        JsonNode corpo = mapper.readTree(resultado.getResponse().getContentAsString());
        assertEquals("ACAO_INVALIDA", corpo.get("erro").asText());
    }

    @Test
    void pedidoInvalidoAoCriar() throws Exception {
