@SpringBootTest
class PedidoFluxoTest {

    @Autowired
    private WebApplicationContext contexto;

    private final ObjectMapper mapper = new ObjectMapper();

    private MockMvc mockMvc() {
        return MockMvcBuilders.webAppContextSetup(contexto).build();
    }

    private JsonNode criar(MockMvc mvc, double valorProdutos, double frete) throws Exception {
        MvcResult resultado = mvc.perform(post("/pedidos")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"valorProdutos\": " + valorProdutos + ", \"frete\": " + frete + "}"))
                .andExpect(status().isCreated())
                .andReturn();
        return mapper.readTree(resultado.getResponse().getContentAsString());
    }

    private JsonNode agir(MockMvc mvc, String id, String acao) throws Exception {
