        agir(mvc, id, "SEPARAR");
        agir(mvc, id, "ENVIAR");
        agir(mvc, id, "ENTREGAR");
        JsonNode resultado = agir(mvc, id, "DEVOLVER");

        assertEquals("DEVOLVIDO", resultado.get("situacao").asText());
        assertEquals(162.50, resultado.get("valorTotal").asDouble());
        assertEquals(150.00, resultado.get("valorReembolsado").asDouble());
        assertEquals(false, resultado.get("estoqueDevolvido").asBoolean());
        assertEquals(true, resultado.get("coletaAgendada").asBoolean());
