        assertEquals("ACAO_NAO_PERMITIDA", corpo.get("erro").asText());

        JsonNode atual = mapper.readTree(mvc.perform(get("/pedidos/" + id)).andReturn().getResponse().getContentAsString());
        assertEquals("PAGO", atual.get("situacao").asText());
